(r, big) => {
  const n = big ? 100000 : r.int(1, 7);
  const ids = r.shuffle(Array.from({ length: n + 1 }, (_, i) => "c" + i));
  const legs = [];
  for (let i = 0; i < n; i++) legs.push([ids[i], ids[i + 1]]);
  return [r.shuffle(legs)];
}

solutions.ts:
function lastStop(legs: string[][]): string {
  for (const [, to] of legs) {
    if (!legs.some(([from]) => from === to)) return to;
  }
  return "";
}

